"""Publish the reviewed native images and instructions as an offline local gallery."""
from pathlib import Path
import html

ROOT=Path(__file__).resolve().parents[1]
OUT=ROOT/'Design/LevelAuthoring/AircraftSeasons'
seasons=[('spring','Весна','Цвітіння, свіжа зелень, вітер і птахи.'),('summer','Літо','Зелене підлісся, комахи, тепле світло й літні звуки.'),('autumn','Осінь','Жовті крони, листопад, опале листя й теплі тіні.'),('winter','Зима','Снігопад, оголені листяні дерева й сніг на відкритих поверхнях; речі під обшивкою захищені.')]
cards=''
for season,label,description in seasons:
    images=''.join(f'<button class="image"><img src="CrashReview/C08/{season}{suffix}.png" alt="{label} — {view}"><span>{view} · натисніть для збільшення</span></button>' for suffix,view in [('', 'Загальний план'),('-detail','Табір і зламані секції зблизька')])
    cards+=f'<article id="{season}"><h2>{label}</h2><p>{description}</p>{images}<p><a href="Levels/{season}/QC_STUDY_AIRCRAFT_{season.upper()}.draft.json" download>Редагована чернетка</a> · <a href="Levels/{season}/QC_STUDY_AIRCRAFT_{season.upper()}.art.json" download>Заморожена геометрія</a></p></article>'
page='''<!doctype html><html lang="uk"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>QuietCamp — давня катастрофа й табір серед уламків</title><style>*{box-sizing:border-box}body{margin:0;background:#18221d;color:#eef0dc;font:17px/1.55 system-ui,sans-serif}main{max-width:1240px;margin:auto;padding:30px}h1{font-size:clamp(25px,4vw,40px);line-height:1.15}a{color:#bddb9a}p{color:#d0d6c5}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:24px}article{background:#253329;border-radius:16px;padding:16px;min-width:0}h2{margin:10px 0}.image{display:block;border:0;padding:0;background:transparent;color:#d0d6c5;width:100%;cursor:zoom-in;margin:12px 0;font:inherit}.image img{display:block;width:100%;border-radius:10px}.image span{display:block;font-size:14px;margin:5px}code{overflow-wrap:anywhere}.hint{padding:18px;background:#2c3f31;border-left:4px solid #bad491;border-radius:8px}dialog{border:0;padding:12px;background:#18221d;color:white;max-width:96vw;max-height:96vh}dialog::backdrop{background:#000b}dialog img{display:block;max-width:90vw;max-height:82vh;object-fit:contain}dialog button{background:#bddb9a;border:0;padding:8px 15px;border-radius:8px;cursor:pointer}.row{display:flex;gap:15px;justify-content:space-between;align-items:center;margin-bottom:8px}@media(max-width:650px){main{padding:16px}.grid{grid-template-columns:1fr}article{padding:12px}}@media print{body{background:white;color:black}dialog{display:none}.grid{grid-template-columns:1fr}article{break-inside:avoid}}</style><main><a href="../index.html">← Довідка майстерні</a><h1>Давня катастрофа. Життя серед уламків.</h1><p>Дві пошкоджені секції лежать під різними кутами й частково заглиблені в землю. Відірване крило, зім’ятий корпус, відкриті шпангоути, заглиблений слід ковзання, старі зламані дерева й дрібні фрагменти пояснюють місце катастрофи. У таборі — зібраний багаж, врятовані крісла, навіс, сушарка, залишені речі й протоптані проходи.</p><div class="hint"><strong>Відкрити в Unity:</strong> QuietCamp → Приклади → Табір між уламками → Весна / Літо / Осінь / Зима. Відкриється нова редагована чернетка у майстерні. Великі та дрібні предмети редагуються окремо, «Настрій» перемикає сезони, «Грати» запускає перевірку, «Зберегти» записує вашу копію.</div><p>Композиція створена через нативний Paint Prefab World Builder. Геометрія, речі та ракурс спільні для всіх сезонів. Старіння запечене в кольори граней; сніг і мокрий блиск слабші під укриттям. При переміщенні укриття маска опадів оновлюється на збереженні, запуску й експорті.</p><section class="grid">'''+cards+'''</section><section><h2>Багаторазове старіння моделей</h2><p>Оберіть декоративний об’єкт у Scene View майстерні → <strong>QuietCamp → Інструменти → Старіння моделей</strong>. Виберіть ефект і матеріал, задайте інтенсивність, розмір ділянок, розподіл, seed та колір. «Переглянути старіння» створює окреме прев’ю; після огляду збережіть варіант або скасуйте. Початкова модель не змінюється; Undo повертає заміну.</p><p>Доступні мох, зношення фарби, іржа сталі, нижній бруд, окиснення алюмінію, патьоки та потемніння від старого вогню. Це редакторський інструмент для packed-моделей майстерні; runtime не потребує редакторських пакетів або додаткових текстур.</p><button class="image"><img src="aging-tool.png" alt="Інтерфейс старіння моделей у Unity"><span>Справжній інтерфейс майстерні</span></button></section><p><a href="../SCENE-STORY-RULES-UA.md">Обов’язкові правила сцени</a> · <a href="crash-review.json">Сім циклів правок для кожного з восьми кадрів</a> · <a href="Levels/spring/ATTRIBUTION.md">Атрибуція літака</a> · <a href="Review/R08/spring.png">Попередня композиція для порівняння</a>.</p><p>Усі зображення захоплені нативно в Unity 6000.6.2f1 з компонентами світу гри. Це кадри без HUD; звук і рух перевіряються в тестовій грі. Крихітні ручні речі дрібні на загальному плані, тому є ближні кадри. Чотири приклади не замінюють кампанію.</p></main><dialog id="zoom"><div class="row"><strong id="label"></strong><button onclick="document.querySelector('#zoom').close()">Закрити · Esc</button></div><img id="large" alt=""></dialog><script>const zoom=document.querySelector('#zoom'),large=document.querySelector('#large');document.querySelectorAll('.image').forEach(b=>b.onclick=()=>{large.src=b.querySelector('img').src;large.alt=b.querySelector('img').alt;document.querySelector('#label').textContent=large.alt;zoom.showModal()});zoom.onclick=e=>{if(e.target===zoom)zoom.close()};</script></html>'''
(OUT/'index.html').write_text(page,encoding='utf-8')
print('Offline crash gallery ready')
